import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.css']
})
export class RegisterComponent implements OnInit {
  registerForm!: FormGroup;
  isSubmitting = false;
  errorMsg = '';
  successMsg = '';

  constructor(private fb: FormBuilder, private authService: AuthService, private router: Router) {}

  ngOnInit(): void {
    this.registerForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(3)]],
      email: ['', [Validators.required, Validators.email]],
      phone: ['', Validators.required],
      passportNumber: ['', Validators.required],
      nationality: ['United States', Validators.required],
      password: ['', [Validators.required, Validators.minLength(6)]],
      confirmPassword: ['', Validators.required]
    }, { validators: this.passwordMatchValidator });
  }

  passwordMatchValidator(g: FormGroup) {
    return g.get('password')?.value === g.get('confirmPassword')?.value
      ? null : { mismatch: true };
  }

  onSubmit(): void {
    if (this.registerForm.invalid) {
      this.registerForm.markAllAsTouched();
      return;
    }

    this.isSubmitting = true;
    this.errorMsg = '';
    this.authService.register(this.registerForm.value).subscribe({
      next: () => {
        this.isSubmitting = false;
        this.successMsg = 'Account registered successfully! Redirecting to login...';
        setTimeout(() => this.router.navigate(['/login']), 2000);
      },
      error: (err) => {
        this.isSubmitting = false;
        this.errorMsg = err.error?.message || 'Registration failed.';
      }
    });
  }
}
<div class="container page-container">
  <div class="auth-card">
    <div class="auth-header">
      <h2>Create Passenger Account</h2>
      <p>Sign up to track baggage, book flights, and accumulate AeroMiles.</p>
    </div>

    <div *ngIf="successMsg" class="alert-success">{{ successMsg }}</div>
    <div *ngIf="errorMsg" class="alert-error">{{ errorMsg }}</div>

    <form [formGroup]="registerForm" (ngSubmit)="onSubmit()">
      <div class="form-group">
        <label class="form-label">Full Name *</label>
        <input type="text" class="form-control" formControlName="name" />
      </div>

      <div class="form-group">
        <label class="form-label">Email Address *</label>
        <input type="email" class="form-control" formControlName="email" />
      </div>

      <div class="form-group">
        <label class="form-label">Mobile Phone Number *</label>
        <input type="text" class="form-control" formControlName="phone" />
      </div>

      <div class="form-group">
        <label class="form-label">Passport Number *</label>
        <input type="text" class="form-control" formControlName="passportNumber" />
      </div>

      <div class="form-group">
        <label class="form-label">Password *</label>
        <input type="password" class="form-control" formControlName="password" />
      </div>

      <div class="form-group">
        <label class="form-label">Confirm Password *</label>
        <input type="password" class="form-control" formControlName="confirmPassword" />
        <div *ngIf="registerForm.hasError('mismatch') && registerForm.get('confirmPassword')?.touched" class="error-text">
          Passwords do not match.
        </div>
      </div>

      <button type="submit" class="btn btn-primary btn-block" [disabled]="isSubmitting">
        {{ isSubmitting ? 'Creating Account...' : 'Register' }}
      </button>
    </form>

    <div class="auth-footer">
      Already have an account? <a routerLink="/login">Sign In</a>
    </div>
  </div>
</div>
